window.AP_HUMAN_GEOGRAPHY_DECKS = [{"id":"aphug-unit-1","name":"AP Human Geography · Unit 1","shortName":"Unit 1","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u1-c1","front":"Geographic location","back":"The position of a feature on Earth's surface, described as absolute location using coordinates or relative location in relation to other places.","sourcePage":1},{"id":"aphug-u1-c2","front":"Place as a geographic concept","back":"A location understood through its distinctive physical and human characteristics, including landscape, culture, population, and built environment.","sourcePage":1},{"id":"aphug-u1-c4","front":"Movement of people, goods, and ideas","back":"One of geography's core themes: the spatial transfer of people, commodities, information, and cultural traits between places through migration, trade, communication, and diffusion.","sourcePage":1},{"id":"aphug-u1-c5","front":"Geographic regions","back":"Areas grouped because they share one or more characteristics. Geographers commonly distinguish formal, functional, and perceptual regions.","sourcePage":1},{"id":"aphug-u1-c6","front":"Physical Geography","back":"The study of Earth's natural features and processes, including climate, landforms, water, soils, ecosystems, and hazards.","sourcePage":1},{"id":"aphug-u1-c7","front":"Human Geography","back":"The study of how people, cultures, economies, and political systems are distributed across space and interact with places and environments.","sourcePage":1},{"id":"aphug-u1-c8","front":"Isoline Maps","back":"Use lines of equal value to represent data like elevation, barometric pressure or temperature","sourcePage":2},{"id":"aphug-u1-c9","front":"Choropleth Maps","back":"A thematic map which shows data by shading patterns or colors.","sourcePage":2},{"id":"aphug-u1-c10","front":"Graduated Symbol Map","back":"A thematic map where the size of the symbol is proportionate to the intensity of the data or variable being mapped.","sourcePage":2},{"id":"aphug-u1-c11","front":"Dot Map","back":"A thematic map where the amount of dots represents the frequency of that data or variable.","sourcePage":2},{"id":"aphug-u1-c12","front":"Cartogram","back":"A thematic map that uses the size of a political unit to display the value of a piece of data.","sourcePage":2},{"id":"aphug-u1-c13","front":"Latitude and climate","back":"Latitude affects solar intensity: places nearer the equator generally receive more direct sunlight, while higher latitudes receive less direct sunlight and are usually cooler.","sourcePage":2},{"id":"aphug-u1-c14","front":"Air masses and climate","back":"Large bodies of air carry the temperature and moisture characteristics of their source regions, shaping regional weather and climate when they move.","sourcePage":2},{"id":"aphug-u1-c15","front":"Continentality","back":"The effect of distance from large bodies of water on climate. Inland places usually have greater annual temperature ranges because land heats and cools faster than water.","sourcePage":2},{"id":"aphug-u1-c16","front":"Elevation and climate","back":"Air temperature generally decreases as elevation rises, so highland climates are often cooler than nearby lowlands at the same latitude.","sourcePage":2},{"id":"aphug-u1-c17","front":"Mountain barriers and climate","back":"Mountains force moist air upward, producing precipitation on windward slopes and drier rain-shadow conditions on leeward slopes.","sourcePage":2},{"id":"aphug-u1-c18","front":"Ocean currents and climate","back":"Warm and cold ocean currents redistribute heat and influence the temperature and moisture of nearby coastal climates.","sourcePage":2},{"id":"aphug-u1-c19","front":"Atmospheric pressure cells","back":"Broad zones of rising or sinking air that shape global winds and precipitation; low pressure favors rising moist air, while high pressure favors sinking dry air.","sourcePage":2},{"id":"aphug-u1-c20","front":"Storm systems","back":"Organized atmospheric disturbances created by pressure differences and interacting air masses, including tropical cyclones and midlatitude storms.","sourcePage":2},{"id":"aphug-u1-c21","front":"High pressure","back":"An atmospheric condition in which air sinks and spreads outward, generally producing clearer and drier weather.","sourcePage":3},{"id":"aphug-u1-c22","front":"low pressure","back":"An atmospheric condition in which air rises and converges, promoting cloud formation, precipitation, and unsettled weather.","sourcePage":3},{"id":"aphug-u1-c26","front":"Goode’s interrupted/homolosine equal","back":"Minimizes distortion due to being interrupted, proportional, interrupts Antarctica and oceans.","sourcePage":3},{"id":"aphug-u1-c27","front":"Conic","back":"Distance and directions are accurate, relatively small zone.","sourcePage":3},{"id":"aphug-u1-c28","front":"Planar projection","back":"Most accurate central point, only shows half earth at a time, stretches out when closer to edge.","sourcePage":3},{"id":"aphug-u1-c29","front":"Mercator","back":"Distorts shape and size of land masses, good direction and maintains distance, used for sea travel.","sourcePage":3},{"id":"aphug-u1-c30","front":"Robinson","back":"Spread distortion across shape, size, and direction, shows landforms correctly, proportional, poles are shown as a straight line, poles are also flat but are too large, longitude not parallel.","sourcePage":3},{"id":"aphug-u1-c31","front":"Gall-peters projection","back":"Sizes of land masses are accurate, shows correct geographic relationships better, inaccurate distances, distorted shapes, latitude and longitude are parallel.","sourcePage":3},{"id":"aphug-u1-c32","front":"Fuller Projection","back":"Doesn’t use cardinal directions, maintains accurate size and shape.","sourcePage":3},{"id":"aphug-u1-c33","front":"Winkel Tripel projection","back":"Rounder in shape with distortion near north and south poles.","sourcePage":3},{"id":"aphug-u1-c34","front":"Primary-sector economies","back":"Economies where a large share of employment and output comes from extracting natural resources through agriculture, fishing, forestry, or mining.","sourcePage":4},{"id":"aphug-u1-c35","front":"Secondary-sector economies","back":"Economies where manufacturing and construction transform raw materials into finished or semi-finished goods.","sourcePage":4},{"id":"aphug-u1-c36","front":"Tertiary-sector economies","back":"Economies dominated by services such as retail, transportation, health care, education, finance, and hospitality.","sourcePage":4},{"id":"aphug-u1-c37","front":"Quaternary-sector economies","back":"Economies with substantial knowledge-based work involving information, research, technology, analysis, and management.","sourcePage":4},{"id":"aphug-u1-c38","front":"MDC","back":"most developed countries - United States, Canada, Japan, Australia, New Zealand and all the western European countries","sourcePage":4},{"id":"aphug-u1-c39","front":"NIC","back":"newly developed countries - China, India, Malaysia, Thailand, the Philippines, South Africa, Turkey, Brazil, and Mexico","sourcePage":4},{"id":"aphug-u1-c40","front":"LDC","back":"least developed countries - Angola, Benin, Burkina Faso, Burundi","sourcePage":4},{"id":"aphug-u1-c41","front":"Cartography","back":"Science of mapmaking, 1st map made by Eratosthenes (276-194 BC), Ptolemy and later chinese and europe continues to advance.","sourcePage":4},{"id":"aphug-u1-c42","front":"Reference maps","back":"Maps designed to show locations of geographic features such as boundaries, roads, cities, rivers, and terrain rather than a single statistical theme.","sourcePage":4},{"id":"aphug-u1-c43","front":"Map scale","back":"Level of detail and the amount of area covered, ex- 1:24,000 / 1in - 1 mile / bar line","sourcePage":4},{"id":"aphug-u1-c44","front":"Scale","back":"The relationship between distance on a map and the corresponding distance on Earth; scale can also mean the geographic level at which a process is analyzed.","sourcePage":4},{"id":"aphug-u1-c45","front":"small scale","back":"A map scale showing a large area with relatively little detail, such as a world map; its representative fraction has a relatively large denominator.","sourcePage":4},{"id":"aphug-u1-c46","front":"large scale","back":"1/25,000 (less distribution, zoomed in), national, global, regional, county scales","sourcePage":4},{"id":"aphug-u1-c47","front":"Scale of analysis","back":"Observational data at a global, national, regional, and local scale; how data is organized and presented on map. - Ex: If the map of the world has countries in different colors, the map scale is global, but the scale of analysis is national because it's coloring different countries.","sourcePage":4},{"id":"aphug-u1-c48","front":"Scale of inquiry","back":"Asking what best scale of analysis would be for a certain topic, how data is grouped together.","sourcePage":4},{"id":"aphug-u1-c49","front":"Absolute distance","back":"Distance in quantitative terms; such as miles or kilometers.","sourcePage":5},{"id":"aphug-u1-c50","front":"Relative distance","back":"Qualitative distance; such as 20 min south, 30 min north, description of place.","sourcePage":5},{"id":"aphug-u1-c51","front":"Clustering","back":"A spatial distribution in which features are concentrated close together rather than evenly dispersed.","sourcePage":5},{"id":"aphug-u1-c52","front":"Dispersal","back":"A spatial distribution in which features are spread apart across an area.","sourcePage":5},{"id":"aphug-u1-c53","front":"Meridians","back":"Run between the North and South poles; 0 degrees (prime meridian) to 180 degrees east/west longitude","sourcePage":5},{"id":"aphug-u1-c54","front":"Parallels","back":"Form right Ls with meridians; latitude; 0 degrees (equator) to 90 North/South. - 24 time zones. 360/24 - 15 degrees, time zone changes every 15 degrees longitude","sourcePage":5},{"id":"aphug-u1-c55","front":"Greenwich mean time (GMT)","back":"At the prime meridian in Greenwich England, master reference time for all points on earth.","sourcePage":5},{"id":"aphug-u1-c56","front":"GPS","back":"Absolute mathematical position; satellites in orbit, tracking stations to monitor, receiver satellites.","sourcePage":5},{"id":"aphug-u1-c57","front":"GIS","back":"A Geographic Information System: computer hardware and software used to store, layer, analyze, and visualize spatial data.","sourcePage":5},{"id":"aphug-u1-c58","front":"Site of a place","back":"The physical characteristics of a location itself, such as terrain, climate, water access, vegetation, and natural resources.","sourcePage":5},{"id":"aphug-u1-c59","front":"Situation of a place","back":"A location's position relative to other places and networks, including transportation routes, markets, resources, and neighboring settlements.","sourcePage":5},{"id":"aphug-u1-c60","front":"Formal region","back":"A uniform homogeneous region; everywhere has one common trait with distinct boundaries separating itself from other regions; may be predominant characteristic rather than universal; Ex: political organization, language, climate.","sourcePage":5},{"id":"aphug-u1-c61","front":"Functional region","back":"Nodal, has a center and characteristics diffuse outward, no function or region; Ex: circulation of a newspaper, pizza delivery, railroad systems, shopping malls","sourcePage":5},{"id":"aphug-u1-c62","front":"Perceptual region","back":"Vernacular, people believe the region exists due to their cultural identity, Ex: Midwest of the United States","sourcePage":5},{"id":"aphug-u1-c63","front":"Culture","back":"What people care about (beliefs, values); what people take care of (materials)","sourcePage":5},{"id":"aphug-u1-c64","front":"Archipelago","back":"A chain or group of islands located close together, such as Japan, Indonesia, or the Philippines.","sourcePage":5},{"id":"aphug-u1-c65","front":"Spatial distribution","back":"The arrangement of a phenomenon across Earth's surface, analyzed through its density, concentration, and pattern.","sourcePage":5},{"id":"aphug-u1-c66","front":"Density","back":"The frequency with which a feature occurs within a defined area, commonly calculated as a count divided by area.","sourcePage":6},{"id":"aphug-u1-c67","front":"Concentration","back":"The extent to which a phenomenon is clustered or dispersed within an area.","sourcePage":6},{"id":"aphug-u1-c68","front":"Spatial pattern","back":"The geometric or geographic arrangement of phenomena across space, such as clustered, dispersed, linear, or random distributions.","sourcePage":6},{"id":"aphug-u1-c69","front":"Relocation diffusion","back":"Spreads through the physical movement of people; Ex: language is brought to new locale by migrants.","sourcePage":6},{"id":"aphug-u1-c70","front":"Expansion diffusion","back":"The spread of a trait outward from its source while it remains influential there; it includes contagious, hierarchical, and stimulus diffusion.","sourcePage":6},{"id":"aphug-u1-c71","front":"Hierarchical diffusion","back":"The spread of a trait through influential people, institutions, or major nodes before it reaches other groups or places.","sourcePage":6},{"id":"aphug-u1-c72","front":"Contagious diffusion","back":"The rapid, widespread diffusion of a trait through direct contact among nearby people or places, without regard to social hierarchy.","sourcePage":6},{"id":"aphug-u1-c73","front":"Stimulus diffusion","back":"The spread of an underlying idea when the original trait itself is rejected or modified to fit a new cultural setting.","sourcePage":6},{"id":"aphug-u1-c74","front":"Reverse hierarchical diffusion","back":"Lower class characteristics spread to higher classes, Ex: hip hop, sagging pants","sourcePage":6},{"id":"aphug-u1-c75","front":"Distance decay","back":"The decrease of an effect due to distance Wallerstein’s three part theory of core-periphery model","sourcePage":6},{"id":"aphug-u1-c76","front":"Core countries","back":"In world-systems theory, wealthy, highly industrialized countries that dominate global trade, finance, technology, and decision-making.","sourcePage":6},{"id":"aphug-u1-c77","front":"Peripheral countries","back":"In world-systems theory, less-developed countries that often supply raw materials and low-cost labor to the global economy.","sourcePage":6},{"id":"aphug-u1-c78","front":"Semi-periphery countries","back":"Argentina, China, Brazil, Mexico, Iran, Indonesia","sourcePage":6},{"id":"aphug-u1-c79","front":"International scale of analysis","back":"A geographic level of analysis that compares or examines relationships among multiple countries.","sourcePage":6},{"id":"aphug-u1-c80","front":"National scale of analysis","back":"Focuses on economic change in a single country Rostow’s Stages of Economic growth: - 5 stages - Key vocab: mass consumption, drive to maturity, traditional society, take off (stage 3)","sourcePage":6},{"id":"aphug-u1-c81","front":"Space time compression","back":"The time it takes for something to reach another place, increasing connectivity, reduces distance decay. Pattern - The geometric arrangement of objects in space","sourcePage":7},{"id":"aphug-u1-c82","front":"Geographic space","back":"The physical area between and around locations in which geographic relationships, distance, distribution, and interaction can be analyzed.","sourcePage":7},{"id":"aphug-u1-c83","front":"Spatial flow","back":"The movement of people, goods, money, information, or ideas between locations.","sourcePage":7},{"id":"aphug-u1-c84","front":"Environment pillar","back":"Sustainable development must value conservation more than wasting resources or preserving all resources.","sourcePage":7},{"id":"aphug-u1-c85","front":"Economy Pillar","back":"To make an effort to set prices of goods based on the costs of the environment, and not just supply and demand.","sourcePage":7},{"id":"aphug-u1-c86","front":"Society Pillar","back":"Modifying the wants of cultures in regards to shelter, food, and clothing to objects that are sustainable","sourcePage":7},{"id":"aphug-u1-c87","front":"Environmental determinism","back":"Physical environment causes social development, environment causes success of a place; increasing for LDCs (least developed countries) before the 2nd and 3rd industrial revolution.","sourcePage":7},{"id":"aphug-u1-c88","front":"Possibilism","back":"People control the environment to a high extent, Ex: Netherlands were built on polders to keep an island above water, Florida can drain everglades and present pollution.","sourcePage":7},{"id":"aphug-u1-c89","front":"Weather","back":"Daily condition of an atmosphere, temperature and precipitation.","sourcePage":7},{"id":"aphug-u1-c90","front":"Precipitation","back":"Water released from the atmosphere to Earth's surface as rain, snow, sleet, or hail.","sourcePage":7},{"id":"aphug-u1-c91","front":"Climate","back":"The long-term average pattern of temperature, precipitation, winds, and other atmospheric conditions in a region.","sourcePage":7},{"id":"aphug-u1-c92","front":"Qualitative data","back":"Opinion based, not measurable; Ex: surveys, polls, interviews","sourcePage":7},{"id":"aphug-u1-c93","front":"Census","back":"Every 10 years is an official count of individuals in a population and collection of geographic data. (how federal funding is determined, helps with moving counties)","sourcePage":7}],"questions":[],"feynmanPrompts":[]},{"id":"aphug-unit-2","name":"AP Human Geography · Unit 2","shortName":"Unit 2","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u2-c8","front":"Contraception","back":"This may go against religious/ cultural beliefs such as roman catholics, fundamentalist protestants, muslims, hindus.","sourcePage":9},{"id":"aphug-u2-c9","front":"Pro-natalist/expansive","back":"Encourages births, Ex: the USSR in 1944 gave awards to women for getting pregnant in order to increase fertility rate, Germany has cross of honor with the german mother on it, India uses family planning","sourcePage":10},{"id":"aphug-u2-c10","front":"Anti-natalist/restrictive","back":"Discourages births, Ex: Chinese had the Later, Longer, Fewer (fewer children, 2 kids allowed in cities, 3 in rural) policy and the one child policy (received rewards: free medical care, schooling, bonuses, etc.)(disobeying results in penalties: education and medical guarantees are withdrawn, wages reduced) 11 Laws of Migration: Most migrants only go a short distance Migration proceeds step by step Migrants going long distance prefer big cities Each migration stream produces a compensation…","sourcePage":10},{"id":"aphug-u2-c13","front":"refugee","back":"has been forced to migrate to avoid a potential threat to his or her life, and or she cannot return for fear of persecution.","sourcePage":11},{"id":"aphug-u2-c14","front":"internally displaced person (IDP)","back":"is similar to a refugee, but he or she has not across an international border.","sourcePage":11},{"id":"aphug-u2-c15","front":"asylum seeker","back":"is a migrant who is looking to be a refugee of another country.","sourcePage":11},{"id":"aphug-u2-c16","front":"Ecumene","back":"Places of permanent human settlement, only a little of the world, 5000 BC to 1900.","sourcePage":11},{"id":"aphug-u2-c17","front":"Colonialism","back":"An endeavor by one country to ascertain settlements and to impose its political, economical, and cultural principles in another territory.","sourcePage":11},{"id":"aphug-u2-c18","front":"Imperialism","back":"Effort by one country to determine settlements and to impose its political, economic and cultural principles on such territory.","sourcePage":11},{"id":"aphug-u2-c19","front":"Carrying capacity","back":"The largest population an environment can support over time without degrading the resource base needed to sustain it.","sourcePage":11},{"id":"aphug-u2-c20","front":"Agricultural density","back":"Ratio of the quantity of famers to amount of arable land (farmers divided by arable land); the US and Canada have a smaller agricultural density than India and Bangladesh, shows amount and advancement of technology being employed, one person can produce more with better machines.","sourcePage":11},{"id":"aphug-u2-c21","front":"Arithmetic density","back":"Total number of objects in an area (total population divided by total land) easiest to get and most frequently used; how unfolded people are; HIGH - a lot of people but little land.","sourcePage":12},{"id":"aphug-u2-c22","front":"Physiological density","back":"The number of people per unit of arable land, used to estimate the pressure a population places on land capable of producing food.","sourcePage":12},{"id":"aphug-u2-c23","front":"Crude Birth Rate (CBR)","back":"The annual number of live births per 1,000 people in a population.","sourcePage":12},{"id":"aphug-u2-c24","front":"Crude Death Rate (CDR)","back":"The annual number of deaths per 1,000 people in a population.","sourcePage":12},{"id":"aphug-u2-c25","front":"Natural increase rate (NIR)","back":"Curious about which population grows, CBR-CDR-NIR, (per 100 because it is a percentage, not per 1,000 people), average current NIR is 1.2%; highest NIR is in South West Asia and Africa.","sourcePage":12},{"id":"aphug-u2-c26","front":"Infant mortality rate (IMR)","back":"Annual number of infant (under 1 years old) deaths per 1,000.","sourcePage":12},{"id":"aphug-u2-c27","front":"Total fertility rate (TFR)","back":"The average number of children a woman is expected to have during her reproductive years, assuming current age-specific birth rates continue.","sourcePage":12},{"id":"aphug-u2-c28","front":"Life expectancy","back":"Average number of years a baby will live based off mortality rates","sourcePage":12},{"id":"aphug-u2-c29","front":"Doubling time","back":"The amount of time it takes for a single population to double in size.","sourcePage":12},{"id":"aphug-u2-c30","front":"Dependency ratio","back":"Number of individuals too old or too young to figure compared to the quantity that may (14 and younger and 65 and older); the larger the dependency ratio the more burden there's on the working population; Ex: 85% Africa, 47% Europe.","sourcePage":12},{"id":"aphug-u2-c31","front":"Sex ratio","back":"Number of males per 100 females, developed countries have more females which live longer. - A population model of male and females can show the culture of a state or a historical event.","sourcePage":12},{"id":"aphug-u2-c32","front":"Malthusian theory","back":"Thomas Malthus's theory that population can grow geometrically while food production grows only arithmetically, creating checks such as famine, disease, and conflict unless population growth slows.","sourcePage":12},{"id":"aphug-u2-c33","front":"Neo-malthusians","back":"Believe earth’s resources can only support a finite population, but they think about all resources not only food production.","sourcePage":13},{"id":"aphug-u2-c34","front":"GDP per capita","back":"Measure of a country's economic output that accounts for its number of individuals.","sourcePage":13},{"id":"aphug-u2-c35","front":"Immigration","back":"Movement into a country or region for temporary or permanent residence.","sourcePage":13},{"id":"aphug-u2-c36","front":"Emigration","back":"Movement out of a country or region to reside elsewhere.","sourcePage":13},{"id":"aphug-u2-c37","front":"Migration","back":"Temporary (possibly permanent) move from one place to another. - #1 reason to maneuver is to search out jobs","sourcePage":13},{"id":"aphug-u2-c38","front":"Intervening obstacle","back":"Environmental or cultural element that stops migration.","sourcePage":13},{"id":"aphug-u2-c39","front":"Intervening opportunity","back":"Cultural, economic, political, environmental factor that causes an individual to prevent migrating to their original destination.","sourcePage":13},{"id":"aphug-u2-c40","front":"Critical distance","back":"The distance beyond which the cost, time, or effort of travel discourages a person from making a trip or migration.","sourcePage":13},{"id":"aphug-u2-c41","front":"Majority-minority population","back":"A population in which groups traditionally classified as racial or ethnic minorities collectively make up more than half of the total.","sourcePage":13},{"id":"aphug-u2-c42","front":"Gravity model","back":"Greater pull in larger communities, bigger cities receive more immigrants.","sourcePage":13},{"id":"aphug-u2-c43","front":"Step migration","back":"Occurs little by little, migrants stop at places along the thanks to their final destination.","sourcePage":13},{"id":"aphug-u2-c44","front":"Chain migration","back":"Process within which legal immigrants may sponsor a loved one for immigration into the US.","sourcePage":13},{"id":"aphug-u2-c45","front":"Intraregional migration","back":"Permanent movement from one location to another within the same region of a country.","sourcePage":13},{"id":"aphug-u2-c46","front":"Xenophobia","back":"Hatred of foreigners based on stereotypes, prejudice, and racism.","sourcePage":13},{"id":"aphug-u2-c47","front":"Counterurbanization","back":"Most prevalent in places rich with natural amenities; Ex: range of mountains States (Colorado, Idaho, Utah, and Wyoming)","sourcePage":13},{"id":"aphug-u2-c48","front":"Ethnocentrism","back":"Judging another culture based on standards of one's own culture. (thinking theirs is better)","sourcePage":13},{"id":"aphug-u2-c49","front":"Interregional migration","back":"Movement from one region to a different region within the same country; Ex: Abundant land on the old american frontier, most jobs and services in are clustered urban areas. Interregional migration - Movement from one region to another region in the same country; Ex: Abundant of land on the old american frontier, most jobs and services in are clustered urban areas. - Russia: Interregional migration was encouraged by the government. The government built new factores and has other economic…","sourcePage":14},{"id":"aphug-u2-c50","front":"Remittances","back":"Money migrants earn in a destination and send to family members or communities in their place of origin.","sourcePage":14},{"id":"aphug-u2-c51","front":"Brain drain","back":"Loss of skilled educated workers. - Largest number of refugees originated from Southwest Asia and sub-saharan Africa. - Preference shown for specific employment placement and family reunification.","sourcePage":14},{"id":"aphug-u2-c52","front":"Quota Act in 1921 and the National Origins Act in 1924","back":"by the U.S. the start of restricted immigration to the U.S.","sourcePage":14},{"id":"aphug-u2-c53","front":"Great Migration in the United States","back":"The twentieth-century movement of millions of African Americans from the rural South to northern, midwestern, and western cities for jobs and to escape segregation and racial violence.","sourcePage":14},{"id":"aphug-u2-c54","front":"Rust Belt","back":"1970’s US near the Great Lakes, stopped employing factory jobs so people would move south.","sourcePage":14},{"id":"aphug-u2-c55","front":"Return migration","back":"Migration back to a person's place or country of origin after living elsewhere.","sourcePage":14}],"questions":[],"feynmanPrompts":[]},{"id":"aphug-unit-3","name":"AP Human Geography · Unit 3","shortName":"Unit 3","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u3-c1","front":"Folk Culture","back":"Popular Culture Other/Mixed Isolated group practicing the Large group of diverse Sports originated as isolated people sharing similar same culture, Ex: amish folk customs and diffused behavior people like other folk cultures via relocation diffusion. - Usually transmitted - Smaller scale and through hierarchical - Football (or soccer) slower transmissions diffusion came from England in from one location to - Diffuses rapidly and the 11th century. another primarily - Transformation from through…","sourcePage":15},{"id":"aphug-u3-c2","front":"Popular Culture","back":"Other/Mixed Large group of diverse Sports originated as isolated people sharing similar folk customs and diffused behavior like other folk cultures via relocation diffusion. - Usually transmitted through hierarchical - Football (or soccer) diffusion came from England in - Diffuses rapidly and the 11th century. - Transformation from extensively from folk to popular sport hearths or nodes of began in the 1800s innovation with help when organized clubs of modern communication, were formed in the…","sourcePage":15},{"id":"aphug-u3-c5","front":"customary beliefs","back":"Sacred Features, Ex: Walls, Door Orientation, Corners - Houses in south","sourcePage":15},{"id":"aphug-u3-c6","front":"Folk music","back":"Traditional music associated with a community or region, usually transmitted through performance and social practice rather than mass commercial distribution.","sourcePage":16},{"id":"aphug-u3-c7","front":"Popular Music","back":"Music written with the south have intent of being sold significance in folk - Performed in front of houses in Madagascar. a paying audience - Often displays a high degree of technical skill - Musicians often have strong connections with other similar musicians that may span the globe - Limited connections with local musicians of different genres","sourcePage":16},{"id":"aphug-u3-c8","front":"Popular Clothing","back":"Clothing styles spread widely through popular culture and often reflect occupation or income more than local environmental conditions.","sourcePage":16},{"id":"aphug-u3-c10","front":"Folk Clothing Preferences","back":"shows occupation or - Style of clothing worn income instead of the in response to environment. distinctive - Business suits worn agricultural by professionals","sourcePage":16},{"id":"aphug-u3-c11","front":"Threats to Pop culture","back":"Sustainability of practice over many non-uniform landscapes - Causes pollution","sourcePage":17},{"id":"aphug-u3-c12","front":"Folk Housing","back":"Available resources resources influence what is built, Ex: stone, grass, sod, and skins. - Two Most Common: Wood, Brick - Climate and local topography influence design of housing structures. - Chinese villages, Ex: All used similar materials to build with. Ex: adobe. Distinct designs in each location attributed to local cultural preference and local geography.","sourcePage":17},{"id":"aphug-u3-c19","front":"Folk/local culture","back":"Traditional culture may reject implementation of new culture.","sourcePage":18},{"id":"aphug-u3-c27","front":"Language as a cultural trait","back":"A structured system of communication that carries cultural identity, spreads through migration and diffusion, and can unify or divide places.","sourcePage":19},{"id":"aphug-u3-c31","front":"Indo-European","back":"The world's most widely distributed language family, including the Germanic, Romance, Balto-Slavic, Indo-Iranian, Hellenic, Celtic, and other branches.","sourcePage":19},{"id":"aphug-u3-c32","front":"Sino-Tibetan","back":"A major language family centered in East and Southeast Asia that includes Sinitic languages such as Mandarin and the Tibeto-Burman languages.","sourcePage":20},{"id":"aphug-u3-c34","front":"Afro-Asiatic","back":"A language family spoken mainly across North Africa, the Horn of Africa, and Southwest Asia; major branches include Semitic, Berber, Cushitic, Chadic, and Egyptian.","sourcePage":20},{"id":"aphug-u3-c35","front":"Altaic","back":"Most speakers are Turkish. It became the official language of many countries that formed after the Soviet Union collapsed, Ex: Azerbaijan, Kazakhstan, and Turkmenistan.","sourcePage":20},{"id":"aphug-u3-c36","front":"Niger-Congo","back":"A large language family spoken across much of sub-Saharan Africa; it includes the Bantu languages and languages such as Swahili.","sourcePage":20},{"id":"aphug-u3-c37","front":"Swahili","back":"First language of 800,000 people. Official language of Tanzania. Spoken by 30 million Africans, the language used to speak with outsiders from different villages.","sourcePage":20},{"id":"aphug-u3-c39","front":"Germanic branch","back":"An Indo-European language branch that includes English, German, Dutch, Swedish, Danish, Norwegian, and related languages.","sourcePage":20},{"id":"aphug-u3-c40","front":"Indo-Iranian branch","back":"The largest Indo-European branch by number of speakers, containing Indo-Aryan languages such as Hindi and Bengali and Iranian languages such as Persian.","sourcePage":21},{"id":"aphug-u3-c41","front":"Balto-Slavic branch","back":"An Indo-European branch containing Baltic languages such as Lithuanian and Latvian and Slavic languages such as Russian, Polish, Czech, and Serbo-Croatian.","sourcePage":21},{"id":"aphug-u3-c42","front":"Romance branch","back":"An Indo-European language branch descended from Latin, including Spanish, Portuguese, French, Italian, and Romanian.","sourcePage":21},{"id":"aphug-u3-c46","front":"Proto-Indo European","back":"The reconstructed common ancestor of the Indo-European languages, believed to have been spoken thousands of years ago before dispersing into distinct branches.","sourcePage":21},{"id":"aphug-u3-c47","front":"Nomadic warrior theory hypothesis","back":"The hypothesis that Proto-Indo-European speakers originated on the Eurasian steppe and spread their language through migration, conquest, and domesticated horses.","sourcePage":21},{"id":"aphug-u3-c48","front":"Sedentary farmer theory","back":"The hypothesis that early Indo-European languages spread from Anatolia with the gradual diffusion of agriculture and settled farming communities.","sourcePage":21},{"id":"aphug-u3-c55","front":"Universalizing Religions","back":"Roman Catholicism southwest and east Europe, Latin America - Protestantism in northwestern","sourcePage":22},{"id":"aphug-u3-c56","front":"Ethnic Religions","back":"Cremate and burn bodies in ganges river - Largest ethnic religion, most in india - Holy books include the Vedas, Bhagavad Geeta, and Upanishads - Monotheistic religion with many forms","sourcePage":25},{"id":"aphug-u3-c57","front":"Animism","back":"Inanimate objects or natural events like disasters have spirits, common in Africa.","sourcePage":25},{"id":"aphug-u3-c58","front":"Judaism","back":"First abrahamic religion, ⅖ Israel, ⅖ US - Bury dead in cemeteries - Western wailing wall, last wall of solomon's temple","sourcePage":25},{"id":"aphug-u3-c61","front":"Cultural appropriation","back":"The adoption of cultural traits from another group, especially when a dominant group uses elements of a marginalized culture without permission, understanding, or respect for their meaning.","sourcePage":27},{"id":"aphug-u3-c62","front":"Cultural relativism","back":"Evaluating a culture according to its own values and context rather than judging it by the standards of another culture.","sourcePage":27},{"id":"aphug-u3-c63","front":"Cultural landscape","back":"The visible imprint of human activity and culture on the natural landscape, including buildings, land use, language, religion, and settlement patterns.","sourcePage":27},{"id":"aphug-u3-c64","front":"Cultural convergence","back":"Two cultures become more similar from frequent interactions.","sourcePage":27},{"id":"aphug-u3-c65","front":"Cultural divergence","back":"A culture splits due to a lack of connection.","sourcePage":27},{"id":"aphug-u3-c66","front":"Acculturation","back":"Adoption of cultural traits from a larger group while still maintaining the original culture.","sourcePage":27},{"id":"aphug-u3-c67","front":"Assimilation","back":"Killing/removal of culture by learning a new culture to replace the previous.","sourcePage":27},{"id":"aphug-u3-c68","front":"Habit","back":"Repetitive act of an individual. For example, wearing jeans everyday.","sourcePage":27},{"id":"aphug-u3-c69","front":"Postmodern architecture","back":"Began 1960s, combines traditional and contemporary architecture.","sourcePage":27},{"id":"aphug-u3-c70","front":"Terroir","back":"Contribution of a location’s physical features on the way food tastes. Also known as the effects of climate on food.","sourcePage":28},{"id":"aphug-u3-c71","front":"Guest worker","back":"European and German countries allow people to temporarily immigrate into their country for a job. China and Southwest Asia are major destinations for migrants.","sourcePage":28},{"id":"aphug-u3-c72","front":"Literary tradition","back":"A language's established system of writing and written works, which helps standardize and preserve it across time and space.","sourcePage":28},{"id":"aphug-u3-c73","front":"Dialects","back":"The regional variation of a language with distinguished vocab, spelling, and pronunciation. It is greatest in rural areas where people have little interaction.","sourcePage":28},{"id":"aphug-u3-c74","front":"Isogloss","back":"Boundary where words/dialect regions can be mapped out.","sourcePage":28},{"id":"aphug-u3-c75","front":"Logograms","back":"Symbols which represent words rather than sounds.","sourcePage":28},{"id":"aphug-u3-c76","front":"Creole language","back":"Mixing of two or more separate languages, Ex: Afrikaans is a mix of dutch and another African language.","sourcePage":28},{"id":"aphug-u3-c77","front":"Multilingual states","back":"States with more than one official language, Ex: Belgium, Switzerland, Nigeria.","sourcePage":28},{"id":"aphug-u3-c78","front":"Revived language","back":"One that was previously extinct but brought back to use. Ex: Hebrew was revived with modern updates.","sourcePage":28},{"id":"aphug-u3-c79","front":"Lingua franca","back":"Language of international communication, Ex: English, Swahili in east Africa, Hindi in South Asia, Russian in Soviet Union.","sourcePage":28},{"id":"aphug-u3-c80","front":"Agnosticism","back":"They believe nothing can be known about whether God exists.","sourcePage":28},{"id":"aphug-u3-c81","front":"Religious branch","back":"A large, fundamental division within a religion, such as Roman Catholicism, Eastern Orthodoxy, and Protestantism within Christianity.","sourcePage":28},{"id":"aphug-u3-c82","front":"Denomination","back":"Division of branch that unites local congregations under a single legal body, Ex: Baptists in Protestant Chrsitianity.","sourcePage":28},{"id":"aphug-u3-c83","front":"Sect","back":"Small group, broken off from an established denomination.","sourcePage":29},{"id":"aphug-u3-c84","front":"Secularism","back":"Dividing state from church, Ex: Renaissance era in Europe with the Catholic church.","sourcePage":29},{"id":"aphug-u3-c85","front":"Sense of place","back":"A feeling that an area has a distinct and meaningful character.","sourcePage":29},{"id":"aphug-u3-c86","front":"Zionism","back":"Policy for establishing a homeland for Jews in palestine.","sourcePage":29},{"id":"aphug-u3-c87","front":"Sharia law","back":"Islamic law which varies on the interpretation of the Karan.","sourcePage":29},{"id":"aphug-u3-c88","front":"Interfaith","back":"Relations, dialogue, or activities involving people or institutions from different religions.","sourcePage":29},{"id":"aphug-u3-c89","front":"Intrafaith","back":"Taking place within, or relevant to a single faith community, Ex: intrafaith marriage.","sourcePage":29},{"id":"aphug-u3-c90","front":"Toponym","back":"Something named after culture or landscape, Ex: Quebec, Ontario, Santa Fe.","sourcePage":29},{"id":"aphug-u3-c91","front":"Syncretism","back":"Blending multiple religions, Ex: halloween is Christian and Pagan.","sourcePage":29},{"id":"aphug-u3-c92","front":"Pilgrimage","back":"Journey for religious purposes, Ex: Muslims to travel to Mecca in the Hajj.","sourcePage":29},{"id":"aphug-u3-c93","front":"Utopian settlement","back":"An ideal community that is constructed around a religious life, Ex: Salt Lake City by the Mormons.","sourcePage":29},{"id":"aphug-u3-c94","front":"Fundamentalism","back":"Literal interpretation and strict adherence to basic principles, Ex: the Taliban’s control over Afghanistan’s government led to strict laws opposing western values such as soccer.","sourcePage":29},{"id":"aphug-u3-c95","front":"Autonomous region","back":"No central authority, shares ideas and cooperates informally.","sourcePage":29},{"id":"aphug-u3-c96","front":"Sacred sites","back":"Ex: Kaaba mosque in Mecca, Jerusalem, Salt Lake City for Mormons, Dome of Rock.","sourcePage":29},{"id":"aphug-u3-c97","front":"Race","back":"Categorization of humans based on skin color or other characteristics such as one’s identity with common ancestors.","sourcePage":29},{"id":"aphug-u3-c98","front":"Minority group","back":"Any recognizable group suffering from discrimination.","sourcePage":29},{"id":"aphug-u3-c99","front":"Ethnic groups","back":"Racial groups based on culture or ethnicity, Ex: Asian American title covers many nationalities. Jews are racially diverse but are bound by a common religion.","sourcePage":29},{"id":"aphug-u3-c100","front":"Ethnicity","back":"The identity a group shares based on traditions from their homeland.","sourcePage":29},{"id":"aphug-u3-c101","front":"Ethnic cleansing","back":"One ethnicity removes another to create a homogeneous region, Ex: Bosnian Muslims in former Yugoslavia were eliminated and a diverse Balkan peninsula is created.","sourcePage":30},{"id":"aphug-u3-c102","front":"Diaspora","back":"Dispersion of people from their homeland, Ex: Jews from Israel.","sourcePage":30},{"id":"aphug-u3-c103","front":"Genocide","back":"Mass killing of a population/ethinicty, Ex: Tutsis murdered by Hutus in Rwanda.","sourcePage":30},{"id":"aphug-u3-c104","front":"Apartheid","back":"Physcial spereation of different races into different geogrpahic areas.","sourcePage":30},{"id":"aphug-u3-c105","front":"Nationality","back":"Identity with a group of people who share legal attachment to a country.","sourcePage":30},{"id":"aphug-u3-c106","front":"Ethnic separatism","back":"Desired regional autonomy expressed by a cultural group within a larger dominant culture.","sourcePage":30}],"questions":[],"feynmanPrompts":[]},{"id":"aphug-unit-4","name":"AP Human Geography · Unit 4","shortName":"Unit 4","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u4-c1","front":"Devolution","back":"Movement of power from the central government to the regional government within a state. It is caused by ethnocultural, economic, and spatial forces. For example... - Scotland wants independence from the EU and ownership of oil resources. - Spain (the Basque and Catalonia each want their own economic autonomy) - Belgium - Flemish (Dutch) in the north and Walloons (French) in the south","sourcePage":31},{"id":"aphug-u4-c2","front":"Landlocked states","back":"Lacks direct outlet to sea, surrounded by other countries, Ex: common in africa, belarus, mongolia, chad, paraguay","sourcePage":32},{"id":"aphug-u4-c3","front":"Gerrymandering","back":"Redrawing legislative boundaries to favor the party in power, illegal in 1985 - Wasted vote: Spreads opposition voters across districts so they are the minority. - Excess vote: Concentrates the opposing voters into a few different districts. - Stacked vote: Link areas of like minded voters into oddly shaped boundaries.","sourcePage":32},{"id":"aphug-u4-c4","front":"United Nations Convention on the Law of the Sea (UNCLOS)","back":"The international legal framework governing maritime boundaries and ocean use, including territorial seas, contiguous zones, exclusive economic zones, and the high seas.","sourcePage":32},{"id":"aphug-u4-c5","front":"Territorial sea","back":"Coastal waters extending up to 12 nautical miles from a state's baseline, where the state exercises sovereignty subject to innocent passage.","sourcePage":32},{"id":"aphug-u4-c6","front":"Contiguous zone","back":"Waters extending up to 24 nautical miles from a state's baseline, where it may enforce customs, immigration, fiscal, and sanitation laws.","sourcePage":32},{"id":"aphug-u4-c7","front":"Exclusive Economic Zone (EEZ)","back":"200 nautical miles, state can explore and manage natural resources","sourcePage":32},{"id":"aphug-u4-c8","front":"High seas","back":"Ocean areas beyond national exclusive economic zones that are open to navigation and use by all states under international law.","sourcePage":32},{"id":"aphug-u4-c10","front":"UN (United nations)","back":"US didn't originally join, Taiwan is most populous state not in the UN, replaced league of nations, purpose is to keep and promote world peace","sourcePage":32},{"id":"aphug-u4-c12","front":"NATO","back":"(North Atlantic Treaty Organization) - 16 democratic states, US, Canada, 14 Europeans, meant to prevent spread of communism of soviets, conflict w/ Muslims","sourcePage":33},{"id":"aphug-u4-c13","front":"Warsaw Pact","back":"Military agreement among communist east Europe to defend each other, provide soviets with allied states.","sourcePage":33},{"id":"aphug-u4-c14","front":"United Nations","back":"(+political) - Created at the end of WW2, facilitates discussion of international problems.","sourcePage":33},{"id":"aphug-u4-c16","front":"EU","back":"(European Union) - 27 countries, promote development of members after WW2, made Euro, used to have barriers on trade but those were removed.","sourcePage":33},{"id":"aphug-u4-c17","front":"COMECON","back":"Promoted trade and sharing of natural resources, included 7 eastern Europe communist states from the Warsaw Pact plus Cuba, Mongolia, and Vietnam. ASEAN(association of southeast asian nation) - indonesia, malaysia, philippines, singapore, thailand, made during vietnam war against communism OPEC(organization of petroleum exporting countries) - middle east countries, control oil production","sourcePage":33},{"id":"aphug-u4-c18","front":"North American Free Trade Agreement (NAFTA)","back":"A trade agreement among Canada, Mexico, and the United States that reduced many barriers to regional trade in 1994; it was replaced by the USMCA in 2020.","sourcePage":33},{"id":"aphug-u4-c19","front":"State (political geography)","back":"A politically organized territory with a permanent population, defined boundaries, a government, and sovereignty over its internal and external affairs.","sourcePage":33},{"id":"aphug-u4-c20","front":"Sovereignty","back":"Inner affairs of a region are independent from control by other states.","sourcePage":33},{"id":"aphug-u4-c21","front":"Nation (political geography)","back":"A group of people who share a strong cultural identity, history, homeland, or political aspirations; a nation does not necessarily control a sovereign state.","sourcePage":33},{"id":"aphug-u4-c22","front":"Nation-state","back":"Population of a country is homogeneous, Ex: Denmark, Slovenia, Japan, Iceland.","sourcePage":33},{"id":"aphug-u4-c23","front":"Stateless nation","back":"Ethnic group without a state, Ex: Kurds in middle east.","sourcePage":33},{"id":"aphug-u4-c24","front":"Microstate","back":"Sovereign state with small population and land, Ex: Monaco.","sourcePage":33},{"id":"aphug-u4-c27","front":"City-state","back":"First states, made of towns and surrounding countryside, walls made to show boundaries, some with military power take over such as the Roman empire, first one arose in Mesopotamia.","sourcePage":34},{"id":"aphug-u4-c28","front":"Self-determination","back":"Concept that ethnicities have the right to govern themselves.","sourcePage":34},{"id":"aphug-u4-c29","front":"Satellite states","back":"Dominated by another state politically and economically.","sourcePage":34},{"id":"aphug-u4-c30","front":"Multi-state nation","back":"Nation stretches across borders of states, Ex: north and south Korea.","sourcePage":34},{"id":"aphug-u4-c31","front":"Multi-ethnic state","back":"A sovereign state whose population contains multiple ethnic groups, such as the United States, Canada, or Nigeria.","sourcePage":34},{"id":"aphug-u4-c32","front":"Multinational state","back":"Country with more than one ethnicity with self determination, Ex: Russia’s caucasus region between black and caspian seas with the azeris, armenians, and georgians.","sourcePage":34},{"id":"aphug-u4-c33","front":"Decolonization","back":"Colonial settlements become independent nations, Ex: 13 colonies.","sourcePage":34},{"id":"aphug-u4-c34","front":"Colony","back":"Territory legally tied to state rather than being independent, Ex: puerto rico, not a part of congress but is home to US citizens.","sourcePage":34},{"id":"aphug-u4-c35","front":"Colonialism","back":"Country establishes settlement to impose its politics, economy, and culture on that territory.","sourcePage":34},{"id":"aphug-u4-c36","front":"Imperialism","back":"Control of territory already occupied by another society.","sourcePage":34},{"id":"aphug-u4-c37","front":"Ethnonationalism","back":"Nationalism in which shared ethnic identity supports claims to political autonomy, sovereignty, or an independent state.","sourcePage":34},{"id":"aphug-u4-c38","front":"State morphology","back":"The shape and territorial configuration of a state, commonly categorized as compact, elongated, prorupted, perforated, or fragmented.","sourcePage":34},{"id":"aphug-u4-c39","front":"Berlin conference","back":"1884-85, european nations claim Africa and created superimposed borders.","sourcePage":34},{"id":"aphug-u4-c40","front":"Versailles peace conference","back":"The 1919 conference where Allied leaders negotiated the post-World War I settlement and redrew borders in Europe and former imperial territories.","sourcePage":34},{"id":"aphug-u4-c41","front":"Apartheid","back":"Domination over a certian race, black in south and Southwest Africa, now Nambia, 1948-90.","sourcePage":34},{"id":"aphug-u4-c42","front":"Cold war","back":"Diplomatic, political, military rivalry between US and soviets, 1945-1991.","sourcePage":34},{"id":"aphug-u4-c43","front":"Organic theory","back":"Theory that states are born and they need nourishment and living space to survive.","sourcePage":34},{"id":"aphug-u4-c44","front":"Heartland theory","back":"Mackinder, early 1900s, best base for world domination is the eurasian heartland.","sourcePage":35},{"id":"aphug-u4-c45","front":"Rimland theory","back":"Spykman, 1944, best base for global domination is eurasian rimland.","sourcePage":35},{"id":"aphug-u4-c46","front":"Choke point","back":"A geographical land feature such as a valley or water way narrowing causing a decrease in forces making their way through.","sourcePage":35},{"id":"aphug-u4-c47","front":"Centripetal forces","back":"Bind or hold together, ex: strong leadership, external threat, education, democracy, russian language for soviet union.","sourcePage":35},{"id":"aphug-u4-c48","front":"Centrifugal forces","back":"Divide or tear state, devolutionary forces, ex: culture/religious/linguistic differences. State - Formal name for country, defined bordes, sovereign gov, recognized, permanent population.","sourcePage":35},{"id":"aphug-u4-c49","front":"Democracy","back":"A political system in which citizens exercise sovereignty directly or through elected representatives in competitive, meaningful elections.","sourcePage":35},{"id":"aphug-u4-c50","front":"Autocracy","back":"A political system in which one ruler or a small group holds concentrated power with limited public participation or institutional restraint.","sourcePage":35},{"id":"aphug-u4-c51","front":"Anocracy","back":"A mixed or transitional political system combining democratic and authoritarian characteristics.","sourcePage":35},{"id":"aphug-u4-c52","front":"Unitary system","back":"Centralized control, no local power, works best in nation states with less cultural differences, smaller states, ex: france, european countries, north korea, kenya, rwanda, china.","sourcePage":35},{"id":"aphug-u4-c53","front":"Confederal systems","back":"Less central power, lots of power to states, confederate states","sourcePage":35},{"id":"aphug-u4-c54","front":"Federal systems","back":"Between unitary and confederal, ex: United states, canada, brazil, india, belgium.","sourcePage":35},{"id":"aphug-u4-c55","front":"Reapportionment","back":"Assigning representation based on population every census.","sourcePage":35},{"id":"aphug-u4-c56","front":"Redistricting","back":"Redrawing district boundaries so each district contains the same amount of people.","sourcePage":35},{"id":"aphug-u4-c57","front":"Political frontier","back":"A zone separating states or political territories where boundaries are weakly defined, unsettled, or under limited governmental control.","sourcePage":35},{"id":"aphug-u4-c58","front":"Border conflicts","back":"Positional, territorial, resource, functional.","sourcePage":35},{"id":"aphug-u4-c59","front":"Shatterbelt","back":"Distress bc of cultural/ethnic conflict, ex: israel, kashmir, east europe during cold war.","sourcePage":35},{"id":"aphug-u4-c61","front":"Cultural boundaries","back":"Geometric (straight line drawn on map, canada and US border), religious, language, ethnic (england,france,portugal,spain boundaries, bc of language or religion), Ex: pakistan and india.","sourcePage":36},{"id":"aphug-u4-c62","front":"Delimited boundary","back":"States disagree about interpretation of documents that define a boundary, Ex: Argentina and Chile's borders on the Andes mountains, drawn on map to show limits of space.","sourcePage":36},{"id":"aphug-u4-c63","front":"Antecedent boundary","back":"Result of area becoming population and gaining value, existed before present settlement occurred and the culture arrived, Ex: US and canada, Ohio R.","sourcePage":36},{"id":"aphug-u4-c64","front":"Subsequent boundary","back":"Developed with the evolution of cultural change, Ex: irsh catholic and pretestant northern ireland, velvet divorce in Czechoslovakia.","sourcePage":36},{"id":"aphug-u4-c65","front":"Open boundary","back":"Boundary people can cross w/o obstacles, Ex: EU allows people to travel between member states.","sourcePage":36},{"id":"aphug-u4-c66","front":"Natural boundary","back":"Based on physical geography, Ex: rivers like Rio Grande.","sourcePage":36},{"id":"aphug-u4-c67","front":"Militarized boundary","back":"Heavily fortified boundaries, discouraged crossing of people, good, info.","sourcePage":36},{"id":"aphug-u4-c68","front":"Superimposed boundary","back":"Political, dividing ethnically similar population by a more powerful country, cause loss of culture, creation of new culture, migration, government change, ineffective governance, multi state nation, multinational state Ex: Kurds in Turkey, Iraq, Iran, and Africa in the Berlin Conference.","sourcePage":36},{"id":"aphug-u4-c69","front":"Relic boundary","back":"Historic boundary, no longer used/nonfunctional, Ex:berlin wall germany, great wall China.","sourcePage":36},{"id":"aphug-u4-c70","front":"Defined boundary","back":"Established by legal document, divides two entities, invisible line.","sourcePage":36},{"id":"aphug-u4-c71","front":"Demarcated boundary","back":"Identified on physical landscape, sign or complex system, ex: DMZ, berlin wall.","sourcePage":36},{"id":"aphug-u4-c72","front":"Geometric boundary","back":"Straight line, doesn’t follow physical features, large-egypt and libya, small-suburbs.","sourcePage":36},{"id":"aphug-u4-c73","front":"Irredentism","back":"Country wants to annex similarly ethnic portion of another country, Ex: Hitler invading czechoslovakia, Somalia - ethiopia conflict over somalis, serbians in bosnia, kashmir region in india, reich trying to connect all german speaking people in europe.","sourcePage":36},{"id":"aphug-u4-c74","front":"Allocational dispute","back":"Disagree over resources at borders, Ex: iraq and Kuwait over rumaila oil field.","sourcePage":36},{"id":"aphug-u4-c75","front":"Functional disputes","back":"Disagree over policies applied along boundary,immigration, Ex: mexico border.","sourcePage":37},{"id":"aphug-u4-c76","front":"Definitional boundary dispute","back":"Two or more parties disagree on interpretation of legal doc or map, Ex: chile and argentina.","sourcePage":37},{"id":"aphug-u4-c77","front":"Locational boundary dispute","back":"Conflict over location or place of boundary, Ex: egypt and sudan","sourcePage":37},{"id":"aphug-u4-c78","front":"Operational boundary dispute","back":"Conflict over operation, Ex: is migration allowed?, US and mexico.","sourcePage":37},{"id":"aphug-u4-c79","front":"Enclaves","back":"Country or part of a country surrounded by territory of another, Ex: lesotho.","sourcePage":37},{"id":"aphug-u4-c80","front":"Exclaves","back":"Parts of a state separated from its main territory by another state or states; an exclave may also be an enclave if it is completely surrounded by one country.","sourcePage":37},{"id":"aphug-u4-c81","front":"Forward capital","back":"Capital city positioned near the international border, confirms the state’s determination to maintain presence. - Capitals that moved somewhere after 1950: Brazil, Nigeria, Pakistan.","sourcePage":37},{"id":"aphug-u4-c82","front":"Geopolitics","back":"Study of interplay between international political relations and environmental context.","sourcePage":37},{"id":"aphug-u4-c83","front":"Supranationalism","back":"3 or more countries form unions for economic, political or cultural reasons.","sourcePage":37},{"id":"aphug-u4-c84","front":"Terrorism","back":"Systematic use of violence to indimidate populations, Ex: 9-11, afrghanistan and pakistan harbor al-qaeda terrorists.","sourcePage":37}],"questions":[],"feynmanPrompts":[]},{"id":"aphug-unit-5","name":"AP Human Geography · Unit 5","shortName":"Unit 5","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u5-c3","front":"Demographic Transition Model","back":"based on population trends - Birth and death rates","sourcePage":41},{"id":"aphug-u5-c5","front":"Extensive agriculture","back":"has limited labor input and extends across large areas of land","sourcePage":42},{"id":"aphug-u5-c6","front":"Intensive agriculture","back":"Involves labor inputs and focuses on small sections of land. - In prehistoric times, the earliest forms of agriculture emerged from hunting and gathering societies.","sourcePage":42},{"id":"aphug-u5-c7","front":"Pastoralism","back":"Agriculture that is based on seasonal movements of animals. - Also known as nomadic herding","sourcePage":42},{"id":"aphug-u5-c8","front":"Cultivars","back":"The practice of producing plants by selective breeding.","sourcePage":42},{"id":"aphug-u5-c9","front":"Multiple cropping","back":"Harvesting more than one crop from the same field during a single year, usually where long growing seasons and sufficient moisture permit it.","sourcePage":42},{"id":"aphug-u5-c10","front":"Staple crop","back":"food is eaten regularly or is apart of the standard diet - Ex: wheat","sourcePage":42},{"id":"aphug-u5-c11","front":"General farming","back":"Multiple crops and animals provide various nutritional intake and nonfood items which includes bones which are used as tools.","sourcePage":42},{"id":"aphug-u5-c12","front":"Mixed farming","back":"Crop farmers domesticated animals to their holdings.","sourcePage":42},{"id":"aphug-u5-c13","front":"Subsistence agriculture","back":"Mixed farming which provides all the necessary items for a household.","sourcePage":42},{"id":"aphug-u5-c14","front":"Extensive subsistence agriculture","back":"This happens when there are a low amount of labor inputs per unit of land.","sourcePage":42},{"id":"aphug-u5-c15","front":"Physiological density","back":"The number of people per unit of arable land, used to estimate the pressure a population places on land capable of producing food.","sourcePage":42},{"id":"aphug-u5-c16","front":"Arable land","back":"Land suitable for cultivation and crop production.","sourcePage":42},{"id":"aphug-u5-c17","front":"Food preservation","back":"Drying, pickling, cooking, and storage jars - Ex: kimchi","sourcePage":42},{"id":"aphug-u5-c18","front":"Specialized crop","back":"A crop produced for a particular market or growing environment rather than as part of broadly diversified farming, such as fruit, vegetables, or nuts.","sourcePage":42},{"id":"aphug-u5-c19","front":"Cash-cropping","back":"Opposite of intensive subsistence farming Extensive agriculture - Crops exchanged for goods, credit, and money.","sourcePage":42},{"id":"aphug-u5-c20","front":"Commercial crop","back":"Transported and sold at markets and then processed into other goods and put on sale. - Crop used for domestic consumption and export.","sourcePage":42},{"id":"aphug-u5-c21","front":"Plantation agriculture","back":"A commercial farming technique where a single crop is grown for the entire year","sourcePage":42},{"id":"aphug-u5-c24","front":"Income disparity","back":"The unequal distribution of income among individuals, groups, regions, or countries.","sourcePage":43},{"id":"aphug-u5-c26","front":"Communist Manifesto","back":"was written by Karl Marx and Friedrich Engels","sourcePage":43},{"id":"aphug-u5-c30","front":"Human ecology","back":"The study of relationships between people, societies, and their physical and biological environments.","sourcePage":43},{"id":"aphug-u5-c31","front":"Food web","back":"A network of interconnected food chains showing how energy and nutrients move among organisms in an ecosystem.","sourcePage":43},{"id":"aphug-u5-c32","front":"Food chain","back":"A linear sequence showing how energy and nutrients pass from producers to consumers and decomposers.","sourcePage":43},{"id":"aphug-u5-c33","front":"Crop Rotation","back":"A planned sequence of different crops on the same field across seasons to maintain soil fertility and reduce pests, diseases, and erosion.","sourcePage":43},{"id":"aphug-u5-c34","front":"Double cropping","back":"Planting two crops one after another in the same plot (within 1 year).","sourcePage":43},{"id":"aphug-u5-c35","front":"Triple cropping","back":"Three crops being planted in a single plot in the same year.","sourcePage":43},{"id":"aphug-u5-c36","front":"Growing season","back":"Every individual crop has its season in which it grows.","sourcePage":43},{"id":"aphug-u5-c37","front":"Spring Wheat","back":"Wheat planted in spring and harvested in late summer or fall, especially in regions with winters too severe for overwintering wheat.","sourcePage":43},{"id":"aphug-u5-c38","front":"Winter wheat","back":"Grows in southern areas near the Great Plains","sourcePage":43},{"id":"aphug-u5-c39","front":"Irrigation","back":"The artificial delivery of water to crops or soil when rainfall is insufficient or unreliable.","sourcePage":43},{"id":"aphug-u5-c40","front":"Aquifers","back":"In countries such as India they are being depleted at rapid rates.","sourcePage":43},{"id":"aphug-u5-c41","front":"Conservation","back":"The practice of preserving and managing natural resources.","sourcePage":43},{"id":"aphug-u5-c42","front":"Conservation agriculture","back":"Becomes important to provide a sustainable farming system without sparing any crop productions.","sourcePage":43},{"id":"aphug-u5-c43","front":"Interplanting","back":"The farmer is allowed to harvest fast-growing crops before the slower ones.","sourcePage":43},{"id":"aphug-u5-c44","front":"Sustainable yield","back":"The # of crops/animals that can be raised with endangering loc resources such as: - Soil - Irrigation - Groundwater","sourcePage":43},{"id":"aphug-u5-c45","front":"Sustainability","back":"Using resources to meet present needs while maintaining environmental systems and future generations' ability to meet their needs.","sourcePage":43},{"id":"aphug-u5-c48","front":"Ethanol","back":"Alcohol that supplements gasoline and burns clearer.","sourcePage":44},{"id":"aphug-u5-c49","front":"Biodiesel","back":"Processed fuel is taken from biological sources such as vegetable oils.","sourcePage":44},{"id":"aphug-u5-c50","front":"Slash and burn agriculture","back":"Farmers shifting one plot of land to another every few years.","sourcePage":44},{"id":"aphug-u5-c51","front":"Fallow","back":"Cultivated land deliberately left unplanted for a period so soil moisture and fertility can recover.","sourcePage":44},{"id":"aphug-u5-c52","front":"Extensive pastoralism","back":"The shifting of animal herds between grazing pastures. - Used in Africa, Middle East, Central Asia","sourcePage":44},{"id":"aphug-u5-c53","front":"Overgrazing","back":"Led to significant amounts of dry grassland being eroded.","sourcePage":44},{"id":"aphug-u5-c55","front":"Soil salinization","back":"Occurs in arid regions where water evaporates which leaves salts behind.","sourcePage":44},{"id":"aphug-u5-c57","front":"Vegetative planting","back":"Shoots, stems, and roots of wild plants are collected and grown together.","sourcePage":44},{"id":"aphug-u5-c58","front":"Seed agriculture","back":"Fertilized seed grains and fruits are collected and planted together.","sourcePage":44},{"id":"aphug-u5-c59","front":"Domestication of plants","back":"The deliberate selection and cultivation of wild plants for useful traits, a key development of the Neolithic agricultural revolution.","sourcePage":44},{"id":"aphug-u5-c60","front":"Horticulture","back":"Plant varieties thrived in various soil and climate conditions were to be cultivated.","sourcePage":44},{"id":"aphug-u5-c61","front":"Animal domestication","back":"Animals are tamed and used for food and profit.","sourcePage":44},{"id":"aphug-u5-c62","front":"Animal husbandry","back":"A branch of agriculture focused on the animals. They are raised for meat, fiber, milk, eggs, and more.","sourcePage":44},{"id":"aphug-u5-c64","front":"The Columbian Exchange","back":"Voyages of Christopher Columbus brought some of the diffusion of animals","sourcePage":44},{"id":"aphug-u5-c65","front":"Hybrids","back":"Offspring of two plants or animals of different species or varieties.","sourcePage":44},{"id":"aphug-u5-c66","front":"Chemical Fertilizers","back":"Manufactured substances added to soil to supply plant nutrients, especially nitrogen, phosphorus, and potassium.","sourcePage":44},{"id":"aphug-u5-c67","front":"Chemical pesticides","back":"Synthetic chemicals used to control insects, weeds, fungi, and other organisms that damage crops.","sourcePage":44},{"id":"aphug-u5-c68","front":"Mechanization","back":"The replacement or supplementation of human and animal labor with machinery in agriculture or industry.","sourcePage":44},{"id":"aphug-u5-c70","front":"Dwarf varieties","back":"Shorter breeds of both wheat and rice were found to be harder and more productive, because the plant spent less time and energy growing a stalk resulting in larger grains.","sourcePage":45},{"id":"aphug-u5-c71","front":"Green Revolution","back":"tropical plant, animal hybrids, and chemical fertilizers began to be used in Third-World agriculture","sourcePage":45},{"id":"aphug-u5-c72","front":"Irrigation pumps","back":"used to move water to dry land farming regions","sourcePage":45},{"id":"aphug-u5-c74","front":"Brahman cattle","back":"A hybrid of a European castle and Zebu castle (from India).","sourcePage":45},{"id":"aphug-u5-c75","front":"Genetic Engineering","back":"Humans altering an organism's genes also known as genetic modification/manipulation. - Ex: BT corn","sourcePage":45},{"id":"aphug-u5-c76","front":"Biotechnology","back":"The use of living organisms, cells, or biological processes to develop products or alter crops and livestock.","sourcePage":45},{"id":"aphug-u5-c77","front":"Factory farming","back":"Large-scale, intensive livestock production in confined facilities designed to maximize output, also called industrial animal agriculture.","sourcePage":45},{"id":"aphug-u5-c78","front":"rBGH","back":"Recombinant Bovine Growth Hormone - used in the production of beef and milk in the US and other countries.","sourcePage":45},{"id":"aphug-u5-c80","front":"Extensive monoculture of Staple crops","back":"Large-scale cultivation of a single staple crop, such as wheat, corn, or soybeans, over a broad area using mechanized methods.","sourcePage":45},{"id":"aphug-u5-c81","front":"Commodity prices","back":"A good that can be traded for products that have similar value.","sourcePage":45},{"id":"aphug-u5-c82","front":"Corporate agriculture or agribusiness","back":"Large extensive farms controlled by single regional business.","sourcePage":45},{"id":"aphug-u5-c83","front":"Downer cattle","back":"Beef cows that are ill or cannot be used for human consumption. - Used in pet food or animal feed","sourcePage":45},{"id":"aphug-u5-c84","front":"GMOs","back":"Genetically modified organisms whose DNA has been altered using genetic engineering to introduce desired traits.","sourcePage":45},{"id":"aphug-u5-c87","front":"Organic","back":"products free of - Pesticides - Antibiotics - Synthetic hormones - Fertilizers","sourcePage":45},{"id":"aphug-u5-c88","front":"Cottage Industry","back":"A traditional type of manufacturing practice by individuals and produced handmade goods for local consumption in the industrial era.","sourcePage":46},{"id":"aphug-u5-c89","front":"Appellation","back":"A recognized geographic name associated with a product's origin and qualities, such as a protected wine or cheese region.","sourcePage":46},{"id":"aphug-u5-c90","front":"Parmigiano-Reggiano","back":"A type of cheese that can carry a specific appellation. - Especially if made in Parma in Italy","sourcePage":46},{"id":"aphug-u5-c91","front":"Suitcase farmers","back":"Farm owners who own land in rural areas but have city jobs.","sourcePage":46},{"id":"aphug-u5-c92","front":"Truck Farms","back":"grow specialty crop during the summer growing season","sourcePage":46},{"id":"aphug-u5-c93","front":"Mediterranean agriculture","back":"domesticated crops - Citrus - oranges, lemons, limes, grapefruit, blood oranges - Nut trees - pistachio, almonds - Palms - different varieties produce fates, palm oils, hearts of palm - Olives - varies both used for eating and pressing for oil - Artichokes - flowers that are fresh for cooking or hearts preserved in oil - Avocados - dark-skinned, has variety and larger green Florida type - Grapes - raisins and fresh fruits pressed for wine production","sourcePage":46},{"id":"aphug-u5-c95","front":"Milk shed","back":"Delivery of fresh milk in surrounding areas of production.","sourcePage":46},{"id":"aphug-u5-c96","front":"Ultra-high temperature Pasteurization","back":"Flash-pasteurized milk that is out in high temperatures and under pressure to prevent the water to turn into steam. Then they store it in a box to prevent contamination","sourcePage":46},{"id":"aphug-u5-c97","front":"Johann Heinrich von Thunen","back":"wrote The Isolated State in 1826 - A described pattern of agricultural land","sourcePage":46},{"id":"aphug-u5-c98","front":"Labor intensive","back":"A large amount of work or needing a lot of work.","sourcePage":46},{"id":"aphug-u5-c99","front":"Von Thunen's model","back":"A land-use model in which agricultural activities form rings around a market according to transportation cost, perishability, and land value.","sourcePage":46}],"questions":[],"feynmanPrompts":[]},{"id":"aphug-unit-6","name":"AP Human Geography · Unit 6","shortName":"Unit 6","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u6-c2","front":"Labor intensive crops","back":"the second ring fruits, garden vegetables. Herbs - Labor intensive animals - dairy cows, poultry - Medicinal crops - herbs - Market gardens - local sales where herbs were grown along with vegetables","sourcePage":47},{"id":"aphug-u6-c3","front":"Managed forest","back":"the third ring used to meet lumber an energy needs for the community","sourcePage":47},{"id":"aphug-u6-c4","front":"Renewable resource","back":"A resource replenished naturally on a human time scale when managed sustainably, such as solar energy, wind, forests, or freshwater.","sourcePage":47},{"id":"aphug-u6-c5","front":"Labor extensive crop","back":"the fourth ring doesn't require a lot of tending - Ex: wheat, barley, rye","sourcePage":47},{"id":"aphug-u6-c6","front":"Grazing in the von Thünen model","back":"Extensive livestock grazing occupies an outer ring because animals need large areas of inexpensive land and can transport themselves to market.","sourcePage":47},{"id":"aphug-u6-c8","front":"Cost to distance relationship","back":"Inverse relation between labors value and distance from the center of the model. - The higher the total labor costs the closer the distance is to the center. - Lower the total labor costs the farther the distance is to the center.","sourcePage":47},{"id":"aphug-u6-c10","front":"Land-rent curve","back":"A model that presents the changes in rent through a mathematical function.","sourcePage":47},{"id":"aphug-u6-c13","front":"Old Asian Tigers","back":"(manufacturing redevelopment period: 1950s -1970s) - Japan, South Korea, Taiwan, Hong Kong, Singapore - Source of development: Foreign aid programs such as the Macarthur Plan","sourcePage":49},{"id":"aphug-u6-c14","front":"New Asian Tigers","back":"(manufacturing redevelopment period: 1980s-1990s) - China, India, Indonesia, Malaysia, Thailand, Vietnam - Source of development: FDI or foreign direct investment World System Theory: Emmanuel Wallerstein developed world systems that explain uneven development around the world.","sourcePage":50},{"id":"aphug-u6-c17","front":"GNI at purchasing power parity (PPP)","back":"Gross national income adjusted for differences in local prices, allowing standards of living and purchasing power to be compared more meaningfully across countries.","sourcePage":51},{"id":"aphug-u6-c19","front":"Primary production","back":"Job deals with the extraction of natural resources. - Ex: mining, energy, forestry, fisheries","sourcePage":51},{"id":"aphug-u6-c20","front":"Secondary production","back":"The processing of raw materials used from the primary sectors.","sourcePage":51},{"id":"aphug-u6-c21","front":"Manufacturing","back":"Secondary-sector activity that transforms raw materials or components into finished or semi-finished products.","sourcePage":51},{"id":"aphug-u6-c22","front":"Tertiary production","back":"Transportation, wholesaling, retailing of goods - Services - Ex: finance","sourcePage":51},{"id":"aphug-u6-c23","front":"Quaternary production -.","back":"Wholesaling, financing, banking, insurance, real estate, advertising, marketing - Business services","sourcePage":51},{"id":"aphug-u6-c24","front":"Quinary production","back":"The highest-level decision-making and leadership functions in government, business, research, education, and nonprofit institutions.","sourcePage":51},{"id":"aphug-u6-c25","front":"Resource-dependent country","back":"A country whose exports, government revenue, or employment relies heavily on a narrow range of natural resources.","sourcePage":51},{"id":"aphug-u6-c26","front":"Mining and energy extraction","back":"Primary-sector activities that remove minerals and energy resources from Earth for processing and use.","sourcePage":51},{"id":"aphug-u6-c27","front":"Fisheries and timer markets","back":"Have more increased value over the years due to less demand.","sourcePage":51},{"id":"aphug-u6-c28","front":"Non-Renewable","back":"A resource that forms too slowly to be replaced on a human time scale, including fossil fuels and most mineral deposits.","sourcePage":51},{"id":"aphug-u6-c29","front":"Renewable","back":"An energy resource replenished naturally on a human time scale, such as solar, wind, hydroelectric, geothermal, or tidal energy.","sourcePage":51},{"id":"aphug-u6-c30","front":"Alternative energy","back":"Energy sources used in place of conventional fossil fuels, often including solar, wind, geothermal, tidal, and nuclear power.","sourcePage":51},{"id":"aphug-u6-c31","front":"Sustainable resource use","back":"Managing renewable resources at a rate that allows replenishment and preserves ecosystem functions and biodiversity over time.","sourcePage":51},{"id":"aphug-u6-c32","front":"Ecosystem","back":"A community of organisms interacting with one another and with the nonliving environment as a connected system.","sourcePage":52},{"id":"aphug-u6-c33","front":"Value-added processing","back":"The transformation of raw goods to more valuable goods.","sourcePage":52},{"id":"aphug-u6-c34","front":"Durable and nondurable goods","back":"A division of production based on the amount of time the specified product is going to be used.","sourcePage":52},{"id":"aphug-u6-c36","front":"Low benefit services","back":"Sectors where labor force tends to be employees on an hourly basis and they review barely any benefits.","sourcePage":52},{"id":"aphug-u6-c37","front":"High-benefit services","back":"Sectors where pay tends to be salaried and includes fringe benefits.","sourcePage":52},{"id":"aphug-u6-c39","front":"Deindustrialized","back":"A shift from manufacturing being the main source of economic production.","sourcePage":52},{"id":"aphug-u6-c40","front":"Foreign competition","back":"A competition involving all countries worldwide.","sourcePage":52},{"id":"aphug-u6-c42","front":"Investment value","back":"The amount of money an investor would pay for a property.","sourcePage":52},{"id":"aphug-u6-c43","front":"Returns on investment","back":"A profitability measure comparing the gain or loss from an investment with its original cost.","sourcePage":52},{"id":"aphug-u6-c50","front":"Restructuring","back":"Reorganization of the system to adapt to changes in the economy.","sourcePage":53},{"id":"aphug-u6-c51","front":"Free-market reforms","back":"An economic system based on supply and demand and has little government control.","sourcePage":53},{"id":"aphug-u6-c55","front":"Newly industrialized countries","back":"States with economies that have made districts shift away from agriculture and towards manufacturing.","sourcePage":53},{"id":"aphug-u6-c56","front":"Infrastructure","back":"The basic systems supporting society and economic activity, including transportation, energy, water, sanitation, and communications networks.","sourcePage":53},{"id":"aphug-u6-c59","front":"Foreign aid or foreign direct investment (FDI)","back":"Funds to develop infrastructure and factories that come from internal sources.","sourcePage":53},{"id":"aphug-u6-c60","front":"Developmental loans","back":"Funds lent by governments or international institutions for infrastructure, education, health, or economic development projects.","sourcePage":53},{"id":"aphug-u6-c61","front":"Donor state","back":"A country that provides development assistance, grants, loans, or technical support to another country.","sourcePage":53},{"id":"aphug-u6-c62","front":"Technology transfer","back":"technical knowledge, training is provided to NIC governments to increase business efficiency","sourcePage":53},{"id":"aphug-u6-c64","front":"World Bank","back":"seeks international development loans that build infrastructure","sourcePage":53},{"id":"aphug-u6-c65","front":"Comparative advantage","back":"The ability of a country or region to produce a good or service at a lower opportunity cost than another producer.","sourcePage":53},{"id":"aphug-u6-c66","front":"Offshoring","back":"Relocating a business process, service, or production activity to another country, often to reduce costs or reach new markets.","sourcePage":53},{"id":"aphug-u6-c67","front":"North versus South Analogy","back":"Some economists use this to describe the developed countries that resemble the North and the less developed countries that resemble the South.","sourcePage":53},{"id":"aphug-u6-c68","front":"Asian Tigers","back":"A term used to describe industrial economics of Asia. Foreign competition and oil shocks of the 1970s both triggered deindustrialization Asian Tigers Offered cheap labor, low-cost land and resources, and few labor and environmental regulations","sourcePage":54},{"id":"aphug-u6-c71","front":"Keiretsu","back":"A Japanese network of independent firms linked through cross-ownership, long-term business relationships, and often a major bank.","sourcePage":54},{"id":"aphug-u6-c72","front":"Chaebol","back":"A large, family-controlled South Korean business conglomerate composed of many affiliated companies.","sourcePage":54},{"id":"aphug-u6-c74","front":"Uneven development","back":"The increasing gap between developmental, technology, and poor stands of living.","sourcePage":54},{"id":"aphug-u6-c77","front":"GNI","back":"(gross national income) - Is the dollar value of all goods and services and the value of exports minus imports measures economic.","sourcePage":54},{"id":"aphug-u6-c79","front":"Trade surplus","back":"A condition in which the value of a country's exports exceeds the value of its imports.","sourcePage":54},{"id":"aphug-u6-c80","front":"Trade deficit","back":"import value exceeds the export value - Imports > Exports","sourcePage":54},{"id":"aphug-u6-c82","front":"Standard of living","back":"Measured by services of productivity that provides for the population.","sourcePage":54},{"id":"aphug-u6-c83","front":"Human development index","back":"Designed by the UN to measure the development of states based on # of social indicators and economic production.","sourcePage":54},{"id":"aphug-u6-c84","front":"Gini coefficient","back":"Measures the level of income disparity between countries' richest and poorest population.","sourcePage":54},{"id":"aphug-u6-c85","front":"Gender-Related Development Index","back":"Same indicated used in HDI but replaced with GDP per capita with income.","sourcePage":55},{"id":"aphug-u6-c86","front":"Gender equality","back":"equality of men and women 5 Stages of Pattern Growth - Traditional society - The economy is focused on primary production such as agriculture and fishing. - A precondition for takeoff - It when the country’s leadership begins to invest in the country’s wealth in infrastructure. - roads, ports, electrification - Takeoff - The economy begins to shift focus into a limited number of industrialized exports. - Drive to maturity - diffusion of technical advancements through the country - Age of mass…","sourcePage":55},{"id":"aphug-u6-c88","front":"Dependency theory","back":"Holds that most LDCs are highly dependent on foreign factories, investments, technology.","sourcePage":55},{"id":"aphug-u6-c89","front":"The cycle of dependency","back":"A pattern in which poorer countries remain reliant on wealthier countries for investment, technology, manufactured goods, or loans.","sourcePage":55},{"id":"aphug-u6-c90","front":"Prebisch thesis","back":"Detailed the dependency of third world economics on first-world loans and investments to pay for buildings and infrastructure.","sourcePage":55},{"id":"aphug-u6-c91","front":"Transnational corporations","back":"Companies that conduct research, operate factories, and sell products in many countries.","sourcePage":55},{"id":"aphug-u6-c92","front":"Economic imperialism","back":"Nations controlled by private business interests that are independent but less-developed.","sourcePage":55},{"id":"aphug-u6-c94","front":"Market stagnation","back":"market expanding slowly - can harm the quality of life of citizens","sourcePage":56},{"id":"aphug-u6-c96","front":"Capital accumulation","back":"The growth of productive assets and financial capital through saving, investment, and reinvested profits.","sourcePage":56},{"id":"aphug-u6-c97","front":"Internalization of economics","back":"Companies are required to deposit profits from factories in LDC banks that invest them locally.","sourcePage":56},{"id":"aphug-u6-c98","front":"Import substitution","back":"Instead of buyindevleg First-world consumer products they produce within LDC.","sourcePage":56},{"id":"aphug-u6-c99","front":"Nationalization of natural resource-based industries","back":"Foreign corporate ownership of oil fields and mines robs the national government and local companies of potential earnings.","sourcePage":56},{"id":"aphug-u6-c100","front":"Profit-sharing agreements","back":"Are permitted to build a new factory on land leased to them by the government.","sourcePage":56},{"id":"aphug-u6-c101","front":"Technology development programs","back":"Counties have used their limited public funds to invest in high-technology equipment and training workers.","sourcePage":56},{"id":"aphug-u6-c103","front":"Ecotourism","back":"Tourism of threatened ecosystems to observe wildlife and protect them.","sourcePage":56},{"id":"aphug-u6-c104","front":"Free-trade zones","back":"Areas that are controlled by corporations rather than the nation-state.","sourcePage":56},{"id":"aphug-u6-c105","front":"Tariffs","back":"Taxes on goods that cross international borders.","sourcePage":56},{"id":"aphug-u6-c106","front":"Command economy","back":"All economic production managed and planned by the central government.","sourcePage":56},{"id":"aphug-u6-c107","front":"Special economic zones (SEZs)","back":"Foreign firms were allowed to build factories in coastal port cities.","sourcePage":56},{"id":"aphug-u6-c108","front":"Export processing zone","back":"Defined as port locations where foreign firms are given special tax privileges to incentivize trade. - Ex: SEZs","sourcePage":56},{"id":"aphug-u6-c109","front":"Core","back":"Nation that is the most developed economies and is influential to the world.","sourcePage":56},{"id":"aphug-u6-c110","front":"Periphery","back":"In world-systems theory, less-developed countries that supply raw materials and low-cost labor and have limited global influence.","sourcePage":56},{"id":"aphug-u6-c111","front":"Semi-periphery","back":"In world-systems theory, countries with characteristics of both core and peripheral economies that mediate between the two.","sourcePage":56},{"id":"aphug-u6-c112","front":"Industrial location","back":"Selection of optimal factory location that minimizes land, labor, resource, and transportation costs.","sourcePage":57},{"id":"aphug-u6-c113","front":"Bulk-reducing manufacturing","back":"Manufacturing in which the finished product weighs less or occupies less volume than its inputs, encouraging factories to locate near raw materials.","sourcePage":57},{"id":"aphug-u6-c114","front":"Bulk-gaining manufacturing","back":"Manufacturing in which the finished product gains weight or volume, encouraging factories to locate near markets to reduce delivery costs.","sourcePage":57},{"id":"aphug-u6-c115","front":"Distance elastic","back":"Can be transported over short or long distances to the steel plant.","sourcePage":57},{"id":"aphug-u6-c118","front":"Mini mills","back":"run by companies such as NUCOR - Located in old steel-producing cities","sourcePage":57},{"id":"aphug-u6-c119","front":"Shelf-life","back":"The length of time a product can be stored before it becomes unsafe, unusable, or loses acceptable quality.","sourcePage":57},{"id":"aphug-u6-c121","front":"Decentralized network","back":"Keep fresh products in stores longer by reducing transportation time.","sourcePage":57},{"id":"aphug-u6-c122","front":"Ubiquitous industry","back":"Bread production is so decentralized that bakeries are found in all cities.","sourcePage":57},{"id":"aphug-u6-c124","front":"Supply chain","back":"Exists when parts are assembled into components that are joined together to create larger finished products.","sourcePage":57},{"id":"aphug-u6-c125","front":"Fordist production","back":"Relied on a single company owning all aspects of production from the steel manufacturer to advertising.","sourcePage":57},{"id":"aphug-u6-c126","front":"Post-Fordist era","back":"Car companies changed and became independent on large networks of regional supply chains.","sourcePage":57},{"id":"aphug-u6-c127","front":"Outsourcing","back":"Common in auto parts and companies reply to several other companies to provide vehicle components.","sourcePage":57},{"id":"aphug-u6-c128","front":"Just in time production","back":"Suppliers send parts to assembly plants on an as-needed basis.","sourcePage":57},{"id":"aphug-u6-c130","front":"Retail services","back":"Services that provide goods for sale to consumers.","sourcePage":57},{"id":"aphug-u6-c131","front":"The spatial margin of profitability","back":"Defined areas of maximization - Areas where local demand for service creates higher revenue than local costs.","sourcePage":57},{"id":"aphug-u6-c132","front":"Footloose industry","back":"Business locations that are not tied to resources or transportation.","sourcePage":58},{"id":"aphug-u6-c134","front":"Creative class","back":"Highly educated workers in knowledge, design, technology, arts, research, and professional fields associated with innovation and urban growth.","sourcePage":58},{"id":"aphug-u6-c136","front":"Agglomeration economies","back":"Exist where firms with related or similar products are located together in clusters or regions.","sourcePage":58},{"id":"aphug-u6-c137","front":"Deglomeration","back":"When a location is overloaded with similar firms and services.","sourcePage":58},{"id":"aphug-u6-c138","front":"Unionized-labor states","back":"Higher payroll and benefit costs which were ingrained into state workforce regulations.","sourcePage":58},{"id":"aphug-u6-c139","front":"Right-to-work states","back":"Regulation does not favor union and does not impact pay benefit costs.","sourcePage":58},{"id":"aphug-u6-c140","front":"Economies of scale","back":"Reductions in average production cost that occur as a firm increases output and spreads fixed costs across more units.","sourcePage":58},{"id":"aphug-u6-c141","front":"Economies of scope","back":"Cost savings gained when a firm produces multiple related products or services using shared resources, technology, or distribution.","sourcePage":58},{"id":"aphug-u6-c142","front":"Product cycle","back":"The stages a product passes through from introduction and growth to maturity and eventual decline or relocation of production.","sourcePage":58},{"id":"aphug-u6-c143","front":"Millennium Development Goals","back":"Eight United Nations targets adopted in 2000 for achievement by 2015, addressing poverty, education, health, equality, and sustainability.","sourcePage":58}],"questions":[],"feynmanPrompts":[]},{"id":"aphug-unit-7","name":"AP Human Geography · Unit 7","shortName":"Unit 7","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u7-c1","front":"Central place theory","back":"Holds that all market areas are focused on a central settlement which is a place of exchange and service.","sourcePage":61},{"id":"aphug-u7-c2","front":"Market hinterland","back":"The surrounding area served by a central place, from which customers travel to obtain its goods and services.","sourcePage":61},{"id":"aphug-u7-c3","front":"Urban hierarchy","back":"The ranking of settlements by population, market area, and the number and complexity of services they provide.","sourcePage":61},{"id":"aphug-u7-c4","front":"Threshold in central place theory","back":"The minimum number of customers needed to support a particular service or business.","sourcePage":61},{"id":"aphug-u7-c5","front":"Range in central place theory","back":"The maximum distance consumers are willing to travel to obtain a particular good or service.","sourcePage":61},{"id":"aphug-u7-c7","front":"Growth poles","back":"Area of a country where specific industries bring employees and thus cause economic growth with the industry, housing market, and local economy.","sourcePage":61},{"id":"aphug-u7-c9","front":"Limited banking regulations","back":"Large corporate and institutional accounts are held to avoid the high auditing costs and king profits taxes of other states.","sourcePage":61},{"id":"aphug-u7-c10","front":"Resource nodes","back":"Towns and cities that were founded due to access to natural resources.","sourcePage":61},{"id":"aphug-u7-c11","front":"Transport nodes","back":"When the location that was founded is an intersection of two or more lines of transportation.","sourcePage":61},{"id":"aphug-u7-c12","front":"Clustered rural settlements","back":"A community that has all residential farm structures of numerous households all aligned or arranged closely together.","sourcePage":61},{"id":"aphug-u7-c13","front":"Dispersed rural settlement","back":"Households are more separated from one another significantly.","sourcePage":61},{"id":"aphug-u7-c14","front":"Circular settlements","back":"A central open space surrounded by a circle of homes.","sourcePage":61},{"id":"aphug-u7-c15","front":"Linear settlements","back":"Settlements arranged in a line along a road, river, coastline, or valley because access follows that corridor.","sourcePage":61},{"id":"aphug-u7-c16","front":"Urban site","back":"The physical characteristics of the land where a city developed, such as terrain, water supply, defensibility, and access to resources.","sourcePage":61},{"id":"aphug-u7-c17","front":"Urban situation","back":"A city's location relative to other places and transportation networks, which influences trade, accessibility, and growth.","sourcePage":62},{"id":"aphug-u7-c18","front":"PLVI","back":"(Peak land value intersection) - Downtown intersection surrounded by the most expensive pieces of real estate.","sourcePage":62},{"id":"aphug-u7-c19","front":"Verticality","back":"Tendency to build skyscrapers that maximize one parcel of urban land.","sourcePage":62},{"id":"aphug-u7-c21","front":"Gentrification","back":"replaced or renovated - Economic reinvestment into existing buildings","sourcePage":62},{"id":"aphug-u7-c22","front":"Garden city movement","back":"Were designed to like European farmhouses with front lawns. - Built for the middle class of Chicago","sourcePage":62},{"id":"aphug-u7-c23","front":"Suburbanization","back":"The movement of population, housing, and economic activity from central cities to surrounding suburban areas.","sourcePage":62},{"id":"aphug-u7-c24","front":"Commuter zone","back":"Represents a wealth area of people who own large tracts of land outside the city.","sourcePage":62},{"id":"aphug-u7-c25","front":"Suitcase farming","back":"Commercial farming in which the operator does not live on the farm and travels to it as needed, often using mechanized production on large holdings.","sourcePage":62},{"id":"aphug-u7-c26","front":"Bid-rent curve","back":"A graph that shows the cost-to-distance relationship of real estate prices in an urban landscape setting.","sourcePage":62},{"id":"aphug-u7-c27","front":"Sector model","back":"Urban structure proposed in 1939 by theorist Homer Hoyt.","sourcePage":62},{"id":"aphug-u7-c28","front":"Ethnic neighborhoods","back":"The result of immigration to industrial cities over previous decades.","sourcePage":62},{"id":"aphug-u7-c29","front":"White flight","back":"The movement of white residents from racially diversifying central cities to suburbs, particularly in the United States during the twentieth century.","sourcePage":62},{"id":"aphug-u7-c30","front":"WASPs","back":"White Anglo-Saxon Protestants, a historically influential ethnocultural group in the United States.","sourcePage":62},{"id":"aphug-u7-c31","front":"Multiple nuclei model","back":"Revolutionary step in the conceptualization of the Anglo-American city.","sourcePage":62},{"id":"aphug-u7-c32","front":"Suburban business districts","back":"They form on the urban periphery and are more scattered and spread out.","sourcePage":62},{"id":"aphug-u7-c33","front":"Suburban CBDs","back":"Concentrations of offices, retail, and services outside downtown, often located near highway interchanges in metropolitan suburbs.","sourcePage":62},{"id":"aphug-u7-c34","front":"Post-industrial city","back":"A city whose economy has shifted from manufacturing toward services, information, finance, technology, and knowledge-based employment.","sourcePage":62},{"id":"aphug-u7-c35","front":"Latin America city model","back":"First represented by Larry Ford and Ernest Griffin in 1980.","sourcePage":62},{"id":"aphug-u7-c36","front":"Laws of the Indies","back":"Dealt with the planning and layout of colonial cities","sourcePage":62},{"id":"aphug-u7-c37","front":"Central plaza","back":"The principal public square in many Latin American cities, traditionally surrounded by government, religious, and commercial buildings.","sourcePage":62},{"id":"aphug-u7-c38","front":"Squatters","back":"People who settle on land that they don't own.","sourcePage":62},{"id":"aphug-u7-c39","front":"Land invasion","back":"Setter in a new area overnight with a large number of families to avoid retributions from landowners.","sourcePage":63},{"id":"aphug-u7-c40","front":"Land tenure","back":"Legal right or title to the land they build their homes on.","sourcePage":63},{"id":"aphug-u7-c42","front":"Basic-sector services","back":"Economic activities that bring income into a settlement by selling goods or services to customers outside the local area.","sourcePage":63},{"id":"aphug-u7-c43","front":"Nonbasic-sector services","back":"Economic activities that primarily serve the local population and circulate income already present within the settlement.","sourcePage":63},{"id":"aphug-u7-c44","front":"Middle-class flight","back":"Inner city and deindustrialization of manufacturing economies prompted even more service providers to relocate.","sourcePage":63},{"id":"aphug-u7-c46","front":"Sprawl","back":"Defined as the expansion of housing, transportation, and commercial development.","sourcePage":63},{"id":"aphug-u7-c47","front":"Growth boundaries","back":"Lines limiting outward urban development to contain sprawl, protect farmland, and encourage denser development.","sourcePage":63},{"id":"aphug-u7-c48","front":"Counter urbanization","back":"is the movement of inner-city suburban residents to rural areas to escape the congestion.","sourcePage":63},{"id":"aphug-u7-c49","front":"Edge city","back":"An area on the outer parts of a city that has a lot of office buildings, shopping malls, hotels, etc.","sourcePage":63},{"id":"aphug-u7-c50","front":"Lateral commuting","back":"Travel between suburban residences and suburban or edge-city workplaces without entering the traditional central city.","sourcePage":63},{"id":"aphug-u7-c51","front":"Counter commuting","back":"Travel from a central city residence to a workplace in the suburbs or an edge city.","sourcePage":63},{"id":"aphug-u7-c52","front":"Colonial cities","back":"Cities with origins as centers of colonial trade of administration.","sourcePage":63},{"id":"aphug-u7-c53","front":"Fall-line cities","back":"Ports that lay upstream on coastal rivers. - This is where navigation is no longer possible by ocean-going ships.","sourcePage":63},{"id":"aphug-u7-c54","front":"Break-in-bulk points","back":"Ships offloaded and packed with outgoing trade.","sourcePage":63},{"id":"aphug-u7-c55","front":"Medieval cities","back":"An urban center that predates the European Renaissance.","sourcePage":63},{"id":"aphug-u7-c56","front":"Gateway cities","back":"Cities that serve as major entry points for migrants, trade, capital, or ideas into a country or region.","sourcePage":63},{"id":"aphug-u7-c57","front":"Entrepot","back":"Describes the port city in which goods are shipped and one price and shipped out to other reports at a higher price.","sourcePage":63},{"id":"aphug-u7-c58","front":"Megacity","back":"Metropolitan area with more than 10 million people.","sourcePage":63},{"id":"aphug-u7-c59","front":"Megapolis","back":"Merging of the urbanized area of two or more cities.","sourcePage":63},{"id":"aphug-u7-c60","front":"Conurbation","back":"A continuous urbanized region formed when expanding cities and towns grow together while retaining separate political identities.","sourcePage":63},{"id":"aphug-u7-c61","front":"World city","back":"A place that is a significant metropolitan area and a global center for finance trade and commerce. Urban hierarchy - World cities ranked in order of importance","sourcePage":63},{"id":"aphug-u7-c62","front":"Primate city","back":"The largest city in the country has at least twice the population of the country’s next largest city.","sourcePage":64},{"id":"aphug-u7-c63","front":"Urban primacy","back":"The dominance of one city over a country's urban system, often measured when the largest city is more than twice the size of the second largest.","sourcePage":64},{"id":"aphug-u7-c64","front":"Decentralization","back":"Is the social process of the population and industry migrating from urban places to suburban areas.","sourcePage":64},{"id":"aphug-u7-c65","front":"Segregation","back":"The spatial separation of social, racial, ethnic, or economic groups through law, discrimination, markets, or institutional practices.","sourcePage":64},{"id":"aphug-u7-c66","front":"Chinatown","back":"Seen as cultural districts but many Chinese, Filippino, Japanese immigrants were forced to live there once.","sourcePage":64},{"id":"aphug-u7-c67","front":"Redlining","back":"Designating neighborhoods on company maps where home mortgage and ensure application would be denied automatically.","sourcePage":64},{"id":"aphug-u7-c68","front":"Restrictive covenants","back":"Private property agreements that historically prohibited sale or occupancy by specified racial, ethnic, or religious groups.","sourcePage":64},{"id":"aphug-u7-c69","front":"Racial steering","back":"Real estate agents advising customers to purchase homes in neighborhoods depending on their race.","sourcePage":64},{"id":"aphug-u7-c70","front":"Invasion and succession","back":"Long term turnover of neighborhood racial and ethnic composition.","sourcePage":64},{"id":"aphug-u7-c72","front":"Historic preservation","back":"Renovating homes in places such as Green Village in NYC and Georgetown in DC.","sourcePage":64},{"id":"aphug-u7-c73","front":"Traffic congestion","back":"When roads are crowded with cars leading to cars moving at slower speeds.","sourcePage":64},{"id":"aphug-u7-c75","front":"Mass transit","back":"High-capacity public transportation such as buses, subways, and commuter rail that moves many passengers along shared routes.","sourcePage":64},{"id":"aphug-u7-c76","front":"Mixed-use buildings","back":"Contain both housing and commercial space. - known as new urbanization","sourcePage":64}],"questions":[],"feynmanPrompts":[]}];
